def traffic_light_state(green: int, yellow: int, red: int, t: int) -> str:
    phase = t % (green + yellow + red)
    if phase < green:
        return "green"
    if phase < green + yellow:
        return "yellow"
    return "red"

def turnstile_final_state(events: list[str]) -> str:
    state = "locked"
    for event in events:
        if event == "coin":
            state = "unlocked"
        elif event == "push":
            state = "locked"
    return state

def elevator_final_floor(start: int, moves: list[int], top: int) -> int:
    floor = start
    for move in moves:
        floor = max(0, min(top, floor + move))
    return floor

def robot_final_position(commands: str) -> tuple[int, int]:
    deltas = {"N": (0, 1), "S": (0, -1), "E": (1, 0), "W": (-1, 0)}
    x = y = 0
    for ch in commands:
        if ch in deltas:
            dx, dy = deltas[ch]
            x += dx
            y += dy
    return (x, y)

def lamps_on_after_presses(n: int, presses: list[int]) -> list[int]:
    on = [False] * n
    for i in presses:
        if 0 <= i < n:
            on[i] = not on[i]
    return [i for i, lit in enumerate(on) if lit]

def thermostat_modes(temps: list[int], low: int, high: int) -> list[str]:
    mid = (low + high) // 2
    mode = "idle"
    out = []
    for t in temps:
        if mode == "idle":
            if t < low:
                mode = "heat"
            elif t > high:
                mode = "cool"
        elif mode == "heat":
            if t >= mid:
                mode = "idle"
        elif t <= mid:
            mode = "idle"
        out.append(mode)
    return out

def pin_lockout_index(attempts: list[str], correct: str, max_failures: int) -> int:
    failures = 0
    for i, pin in enumerate(attempts):
        if pin == correct:
            failures = 0
        else:
            failures += 1
            if failures >= max_failures:
                return i
    return -1

def parking_peak_occupancy(events: list[str], capacity: int) -> int:
    count = peak = 0
    for event in events:
        if event == "in" and count < capacity:
            count += 1
        elif event == "out" and count > 0:
            count -= 1
        peak = max(peak, count)
    return peak

def run_stack_machine(ops: list[str]) -> list[int]:
    stack: list[int] = []
    for op in ops:
        parts = op.split()
        name = parts[0]
        if name == "push":
            stack.append(int(parts[1]))
        elif name == "pop":
            if stack:
                stack.pop()
        elif name == "add":
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
        elif name == "dup":
            if stack:
                stack.append(stack[-1])
    return stack

def count_signal_edges(signal: str) -> tuple[int, int]:
    rising = falling = 0
    for prev, cur in zip(signal, signal[1:]):
        if prev == "0" and cur == "1":
            rising += 1
        elif prev == "1" and cur == "0":
            falling += 1
    return (rising, falling)

def washing_machine_state(events: list[str]) -> str:
    following = {
        "filling": "washing",
        "washing": "rinsing",
        "rinsing": "draining",
        "draining": "idle",
    }
    state = "idle"
    for event in events:
        if event == "start" and state == "idle":
            state = "filling"
        elif event == "next" and state in following:
            state = following[state]
        elif event == "cancel" and state in ("filling", "washing", "rinsing"):
            state = "draining"
    return state

def life_next_generation(grid: list[str]) -> list[str]:
    rows = len(grid)
    result = []
    for r in range(rows):
        cols = len(grid[r])
        new_row = []
        for c in range(cols):
            alive = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < rows and 0 <= cc < len(grid[rr]) and grid[rr][cc] == "#":
                        alive += 1
            if alive == 3 or (alive == 2 and grid[r][c] == "#"):
                new_row.append("#")
            else:
                new_row.append(".")
        result.append("".join(new_row))
    return result

def langton_black_cells(steps: int) -> int:
    black: set[tuple[int, int]] = set()
    x = y = 0
    dx, dy = 0, 1
    for _ in range(steps):
        if (x, y) in black:
            dx, dy = -dy, dx
            black.remove((x, y))
        else:
            dx, dy = dy, -dx
            black.add((x, y))
        x += dx
        y += dy
    return len(black)

def elementary_automaton(cells: str, rule: int, steps: int) -> str:
    state = [int(ch) for ch in cells]
    n = len(state)
    for _ in range(steps):
        state = [
            (rule >> (4 * state[i - 1] + 2 * state[i] + state[(i + 1) % n])) & 1
            for i in range(n)
        ]
    return "".join(map(str, state))

def vending_session(events: list[str], price: int) -> list[str]:
    credit = 0
    out = []
    for event in events:
        parts = event.split()
        if parts[0] == "coin":
            credit += int(parts[1])
        elif parts[0] == "select":
            if credit >= price:
                out.append("item")
                if credit > price:
                    out.append(f"change {credit - price}")
                credit = 0
            else:
                out.append(f"need {price - credit}")
        elif parts[0] == "refund" and credit > 0:
            out.append(f"refund {credit}")
            credit = 0
    return out

def debounce_signal(samples: list[int], k: int) -> list[int]:
    out = []
    state = None
    run_value = None
    run_length = 0
    for s in samples:
        if s == run_value:
            run_length += 1
        else:
            run_value, run_length = s, 1
        if state is None:
            state = s
        elif s != state and run_length >= k:
            state = s
        out.append(state)
    return out

def binary_divisible_by(bits: str, k: int) -> bool:
    remainder = 0
    for b in bits:
        remainder = (2 * remainder + (b == "1")) % k
    return remainder == 0

def run_dfa(transitions: dict[tuple[str, str], str], start: str,
            accepting: set[str], word: str) -> bool:
    state = start
    for symbol in word:
        key = (state, symbol)
        if key not in transitions:
            return False
        state = transitions[key]
    return state in accepting

def tcp_like_state(events: list[str]) -> str:
    table = {
        ("CLOSED", "listen"): "LISTEN",
        ("LISTEN", "syn"): "SYN_RCVD",
        ("SYN_RCVD", "ack"): "ESTABLISHED",
        ("ESTABLISHED", "close"): "FIN_WAIT",
        ("FIN_WAIT", "ack"): "CLOSED",
    }
    state = "CLOSED"
    for event in events:
        if state == "ERROR":
            break
        if event == "reset":
            state = "CLOSED"
        else:
            state = table.get((state, event), "ERROR")
    return state

def robot_with_obstacles(width: int, height: int, obstacles: set[tuple[int, int]],
                         commands: str) -> tuple[int, int, str]:
    headings = "NESW"
    deltas = {"N": (0, 1), "E": (1, 0), "S": (0, -1), "W": (-1, 0)}
    x = y = 0
    h = 0
    for cmd in commands:
        if cmd == "L":
            h = (h - 1) % 4
        elif cmd == "R":
            h = (h + 1) % 4
        elif cmd == "F":
            dx, dy = deltas[headings[h]]
            nx, ny = x + dx, y + dy
            if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles:
                x, y = nx, ny
    return (x, y, headings[h])

def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    g = [row[:] for row in grid]
    rows = len(g)
    stack = [(r, c) for r in range(rows) for c in range(len(g[r])) if g[r][c] >= 4]
    while stack:
        r, c = stack.pop()
        if g[r][c] < 4:
            continue
        q, g[r][c] = divmod(g[r][c], 4)
        for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= rr < rows and 0 <= cc < len(g[rr]):
                g[rr][cc] += q
                if g[rr][cc] >= 4:
                    stack.append((rr, cc))
    return g

def parse_csv_record(line: str) -> list[str]:
    fields = []
    buf = []
    state = "start"  # start | unquoted | quoted | quote_in_quoted
    for ch in line:
        if state == "start":
            if ch == '"':
                state = "quoted"
            elif ch == ",":
                fields.append("")
            else:
                buf.append(ch)
                state = "unquoted"
        elif state == "unquoted":
            if ch == ",":
                fields.append("".join(buf))
                buf = []
                state = "start"
            else:
                buf.append(ch)
        elif state == "quoted":
            if ch == '"':
                state = "quote_in_quoted"
            else:
                buf.append(ch)
        else:  # just saw a quote inside a quoted field
            if ch == '"':
                buf.append('"')
                state = "quoted"
            elif ch == ",":
                fields.append("".join(buf))
                buf = []
                state = "start"
            else:
                buf.append(ch)
                state = "unquoted"
    fields.append("".join(buf))
    return fields

from collections import OrderedDict


def lru_hit_count(capacity: int, accesses: list[int]) -> int:
    cache: OrderedDict[int, None] = OrderedDict()
    hits = 0
    if capacity <= 0:
        return 0
    for key in accesses:
        if key in cache:
            hits += 1
            cache.move_to_end(key)
        else:
            if len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = None
    return hits

from typing import Optional


def run_register_machine(program: list[str], max_steps: int) -> Optional[dict[str, int]]:
    regs: dict[str, int] = {}

    def value(token: str) -> int:
        if token.isalpha():
            return regs.get(token, 0)
        return int(token)

    pc = 0
    steps = 0
    while 0 <= pc < len(program):
        if steps == max_steps:
            return None
        op, x, y = program[pc].split()
        steps += 1
        if op == "jnz":
            if value(x) != 0:
                pc += value(y)
                continue
        elif op == "set":
            regs[x] = value(y)
        elif op == "add":
            regs[x] = regs.get(x, 0) + value(y)
        elif op == "mul":
            regs[x] = regs.get(x, 0) * value(y)
        pc += 1
    return regs

