from typing import Optional


def life_cycle_detection(grid: list[str], max_generations: int) -> Optional[tuple[int, int]]:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def step(state: tuple[str, ...]) -> tuple[str, ...]:
        out = []
        for r in range(rows):
            row = []
            for c in range(cols):
                n = sum(
                    state[rr][cc] == "#"
                    for rr in range(max(0, r - 1), min(rows, r + 2))
                    for cc in range(max(0, c - 1), min(cols, c + 2))
                    if (rr, cc) != (r, c)
                )
                row.append("#" if n == 3 or (n == 2 and state[r][c] == "#") else ".")
            out.append("".join(row))
        return tuple(out)

    state = tuple(grid)
    seen = {state: 0}
    for gen in range(1, max_generations + 1):
        state = step(state)
        if state in seen:
            return (seen[state], gen - seen[state])
        seen[state] = gen
    return None

def minimal_dfa_state_count(num_states: int, alphabet: str,
                            delta: dict[tuple[int, str], int],
                            accepting: set[int]) -> int:
    reachable = {0}
    frontier = [0]
    while frontier:
        s = frontier.pop()
        for ch in alphabet:
            t = delta[(s, ch)]
            if t not in reachable:
                reachable.add(t)
                frontier.append(t)

    block = {s: int(s in accepting) for s in reachable}
    count = len(set(block.values()))
    while True:
        signatures: dict[tuple, int] = {}
        new_block = {}
        for s in sorted(reachable):
            sig = (block[s],) + tuple(block[delta[(s, ch)]] for ch in alphabet)
            new_block[s] = signatures.setdefault(sig, len(signatures))
        if len(signatures) == count:
            return count
        block, count = new_block, len(signatures)

