def nfa_accepts(transitions: dict[tuple[int, str], set[int]], start: int,
                accepting: set[int], word: str) -> bool:
    def closure(states: set[int]) -> set[int]:
        result = set(states)
        stack = list(states)
        while stack:
            s = stack.pop()
            for t in transitions.get((s, ""), ()):
                if t not in result:
                    result.add(t)
                    stack.append(t)
        return result

    current = closure({start})
    for ch in word:
        moved = set()
        for s in current:
            moved |= transitions.get((s, ch), set())
        current = closure(moved)
        if not current:
            return False
    return bool(current & accepting)

from typing import Optional


def run_turing_machine(rules: dict[tuple[str, str], tuple[str, str, str]], tape: str,
                       start: str, halt: str, max_steps: int) -> Optional[str]:
    cells = {i: ch for i, ch in enumerate(tape) if ch != "_"}
    head = 0
    state = start
    steps = 0
    while state != halt:
        key = (state, cells.get(head, "_"))
        if key not in rules:
            break
        if steps == max_steps:
            return None
        write, move, state = rules[key]
        if write == "_":
            cells.pop(head, None)
        else:
            cells[head] = write
        head += 1 if move == "R" else -1
        steps += 1
    if not cells:
        return ""
    lo, hi = min(cells), max(cells)
    return "".join(cells.get(i, "_") for i in range(lo, hi + 1))
